<div class="panel mb-3"><form method="get" class="form-inline"><label class="mr-2">Dari</label><input class="form-control mr-3" type="date" name="from" value="<?=html_escape($from)?>"><label class="mr-2">Sampai</label><input class="form-control mr-3" type="date" name="to" value="<?=html_escape($to)?>"><button class="btn btn-pink">Filter</button></form></div><div class="panel"><h5>Creator Performance</h5><div class="table-responsive"><table class="table table-darkish"><thead><tr><th>Creator</th><th>Videos</th><th>Views</th><th>Likes</th><th>Comments</th><th>Shares</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=html_escape($r['creator'])?></td><td><?=$r['videos']?></td><td><?=number_format($r['views'])?></td><td><?=number_format($r['likes'])?></td><td><?=number_format($r['comments'])?></td><td><?=number_format($r['shares'])?></td></tr><?php endforeach;?></tbody></table></div><button onclick="window.print()" class="btn btn-outline-info">Print Report</button></div>
